BEGIN;
CREATE TABLE IF NOT EXISTS movement_type_wizard_steps(id BIGSERIAL PRIMARY KEY,company_id INT NOT NULL,branch_id INT NOT NULL,movement_type_id BIGINT NOT NULL REFERENCES movement_types(id) ON DELETE CASCADE,step_code VARCHAR(30) NOT NULL,step_order INT NOT NULL,completed BOOLEAN NOT NULL DEFAULT FALSE,configuration JSONB NOT NULL DEFAULT '{}'::jsonb,updated_by INT REFERENCES users(id),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),FOREIGN KEY(company_id,branch_id) REFERENCES branches(company_id,id),UNIQUE(company_id,branch_id,movement_type_id,step_code));
CREATE TABLE IF NOT EXISTS movement_financial_config(id BIGSERIAL PRIMARY KEY,company_id INT NOT NULL,branch_id INT NOT NULL,movement_type_id BIGINT NOT NULL REFERENCES movement_types(id) ON DELETE CASCADE,generates_financial BOOLEAN NOT NULL DEFAULT FALSE,direction VARCHAR(10),installment_count INT NOT NULL DEFAULT 1,payment_term_days INT NOT NULL DEFAULT 0,cost_center_required BOOLEAN NOT NULL DEFAULT FALSE,allocation_required BOOLEAN NOT NULL DEFAULT FALSE,configuration JSONB NOT NULL DEFAULT '{}'::jsonb,FOREIGN KEY(company_id,branch_id) REFERENCES branches(company_id,id),UNIQUE(company_id,branch_id,movement_type_id));
CREATE TABLE IF NOT EXISTS movement_fiscal_config(id BIGSERIAL PRIMARY KEY,company_id INT NOT NULL,branch_id INT NOT NULL,movement_type_id BIGINT NOT NULL REFERENCES movement_types(id) ON DELETE CASCADE,fiscal_nature_id BIGINT REFERENCES fiscal_natures(id),document_model VARCHAR(10),generates_posting BOOLEAN NOT NULL DEFAULT FALSE,generates_nfe BOOLEAN NOT NULL DEFAULT FALSE,series VARCHAR(3),environment VARCHAR(15) NOT NULL DEFAULT 'HOMOLOGACAO',send_mode VARCHAR(20) NOT NULL DEFAULT 'MANUAL',allows_item_nature BOOLEAN NOT NULL DEFAULT FALSE,configuration JSONB NOT NULL DEFAULT '{}'::jsonb,FOREIGN KEY(company_id,branch_id) REFERENCES branches(company_id,id),UNIQUE(company_id,branch_id,movement_type_id));
CREATE TABLE IF NOT EXISTS movement_accounting_config(id BIGSERIAL PRIMARY KEY,company_id INT NOT NULL,branch_id INT NOT NULL,movement_type_id BIGINT NOT NULL REFERENCES movement_types(id) ON DELETE CASCADE,generates_accounting BOOLEAN NOT NULL DEFAULT FALSE,posting_mode VARCHAR(15) NOT NULL DEFAULT 'MANUAL',accounting_event_code VARCHAR(30),debit_account VARCHAR(40),credit_account VARCHAR(40),history_template TEXT,cost_center_required BOOLEAN NOT NULL DEFAULT FALSE,configuration JSONB NOT NULL DEFAULT '{}'::jsonb,FOREIGN KEY(company_id,branch_id) REFERENCES branches(company_id,id),UNIQUE(company_id,branch_id,movement_type_id));
CREATE TABLE IF NOT EXISTS movement_retention_config(id BIGSERIAL PRIMARY KEY,company_id INT NOT NULL,branch_id INT NOT NULL,movement_type_id BIGINT NOT NULL REFERENCES movement_types(id) ON DELETE CASCADE,tax_id BIGINT REFERENCES fiscal_taxes(id),application_level VARCHAR(15) NOT NULL DEFAULT 'ITEM',control_mode VARCHAR(15) NOT NULL DEFAULT 'NAO_USA',default_rate NUMERIC(12,6),default_value NUMERIC(15,2),deducts_financial BOOLEAN NOT NULL DEFAULT TRUE,generates_separate_title BOOLEAN NOT NULL DEFAULT FALSE,nature_of_income VARCHAR(30),active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(company_id,branch_id) REFERENCES branches(company_id,id));
CREATE TABLE IF NOT EXISTS movement_accounting_entries(id BIGSERIAL PRIMARY KEY,company_id INT NOT NULL,branch_id INT NOT NULL,movement_id INT NOT NULL REFERENCES billing_movements(id) ON DELETE CASCADE,entry_date DATE NOT NULL DEFAULT CURRENT_DATE,debit_account VARCHAR(40) NOT NULL,credit_account VARCHAR(40) NOT NULL,amount NUMERIC(15,2) NOT NULL,history TEXT,status VARCHAR(20) NOT NULL DEFAULT 'PENDENTE',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS movement_retentions(id BIGSERIAL PRIMARY KEY,company_id INT NOT NULL,branch_id INT NOT NULL,movement_id INT NOT NULL REFERENCES billing_movements(id) ON DELETE CASCADE,movement_item_id INT REFERENCES billing_movement_items(id) ON DELETE CASCADE,tax_id BIGINT REFERENCES fiscal_taxes(id),tax_base NUMERIC(15,2) NOT NULL DEFAULT 0,rate NUMERIC(12,6) NOT NULL DEFAULT 0,amount NUMERIC(15,2) NOT NULL DEFAULT 0,nature_of_income VARCHAR(30),status VARCHAR(20) NOT NULL DEFAULT 'CALCULADA');
ALTER TABLE billing_movements ADD COLUMN IF NOT EXISTS accounting_status VARCHAR(30) NOT NULL DEFAULT 'NAO_CONTABILIZADO',ADD COLUMN IF NOT EXISTS retention_total NUMERIC(15,2) NOT NULL DEFAULT 0,ADD COLUMN IF NOT EXISTS net_total NUMERIC(15,2) NOT NULL DEFAULT 0;
ALTER TABLE nfe_transmissions ADD COLUMN IF NOT EXISTS response_xml TEXT,ADD COLUMN IF NOT EXISTS receipt_number VARCHAR(30),ADD COLUMN IF NOT EXISTS schema_version VARCHAR(20) NOT NULL DEFAULT '4.00';
COMMIT;
